def weather_csv_bytes() -> bytes:
    import base64
    import gzip
    import hashlib

    raw = gzip.decompress(base64.b64decode("".join(WEATHER_CSV_GZ_B64)))
    if hashlib.sha256(raw).hexdigest() != WEATHER_CSV_SHA256:
        raise ValueError("SHA-256 погодного CSV не совпадает")
    return raw
